const BASE_SEA_CROSSINGS: readonly [number,number][] = [[31140,31138],[20939,21421],[17547,16830],[34200,34202],[31294,29621],[16668,16429],[30573,31293],[36636,35673],[37155,35955],[31289,31530]];
// v0.7: the same geographical extent contains 2.25x as many conquerable
// sectors (360x240 instead of 240x160). These are actual simulated cells,
// not a camera zoom or larger sprites. Nearest-source-mask resampling preserves
// the original Natural Earth land classification; coastlines stay simplified.
export const LAND_ROWS: readonly string[] = Array.from({ length: MAP_HEIGHT }, (_, y) => {
  const source = BASE_LAND_ROWS[Math.floor(y * BASE_HEIGHT / MAP_HEIGHT)];
  return Array.from({ length: MAP_WIDTH }, (_, x) => source[Math.floor(x * BASE_WIDTH / MAP_WIDTH)]).join('');
});
const expandEndpoint = (index: number): number => {
  const bx = index % BASE_WIDTH, by = Math.floor(index / BASE_WIDTH);
  return Math.floor((by + 0.5) * MAP_HEIGHT / BASE_HEIGHT) * MAP_WIDTH
    + Math.floor((bx + 0.5) * MAP_WIDTH / BASE_WIDTH);
};
// Crossings are physical embark/disembark sites. Normal land assaults NEVER
// traverse these links, even though the optional topology graph includes them.
export const SEA_CROSSINGS: readonly [number,number][] =
  BASE_SEA_CROSSINGS.map(([a,b]) => [expandEndpoint(a),expandEndpoint(b)] as [number,number]);
